#!/usr/bin/env python3
"""Generate synthetic Spider databases from tables.json schema info.

Creates SQLite databases with synthetic data for each Spider database.
Used when original databases can't be downloaded (e.g., Google Drive blocked).
"""

import json
import os
import random
import sqlite3
import string

TABLES_JSON = "/root/autodl-tmp/test_suite_tmp/tables.json"
OUTPUT_DIR = "/root/autodl-tmp/spider_data/database"
ROWS_PER_TABLE = 15
SEED = 42

random.seed(SEED)

# Sample data pools
NAMES = ["Alice", "Bob", "Charlie", "Diana", "Eve", "Frank", "Grace", "Henry",
         "Iris", "Jack", "Kate", "Leo", "Mia", "Noah", "Olivia", "Paul",
         "Quinn", "Rose", "Sam", "Tina", "Uma", "Victor", "Wendy", "Xander"]
CITIES = ["New York", "London", "Tokyo", "Paris", "Berlin", "Sydney", "Toronto",
          "Mumbai", "Beijing", "Seoul", "Moscow", "Cairo", "Rome", "Madrid",
          "Amsterdam", "Dublin", "Vienna", "Prague", "Warsaw", "Athens"]
COUNTRIES = ["USA", "UK", "Japan", "France", "Germany", "Australia", "Canada",
             "India", "China", "South Korea", "Russia", "Egypt", "Italy", "Spain"]
WORDS = ["alpha", "beta", "gamma", "delta", "epsilon", "zeta", "eta", "theta",
         "iota", "kappa", "lambda", "mu", "nu", "xi", "omicron", "pi",
         "rho", "sigma", "tau", "upsilon", "phi", "chi", "psi", "omega"]


def gen_text_value(col_name_lower):
    cn = col_name_lower
    if any(w in cn for w in ["name", "first", "last"]):
        return random.choice(NAMES)
    if any(w in cn for w in ["city", "location", "address", "place"]):
        return random.choice(CITIES)
    if any(w in cn for w in ["country", "nation"]):
        return random.choice(COUNTRIES)
    if any(w in cn for w in ["date", "time", "year"]):
        y = random.randint(1990, 2025)
        m = random.randint(1, 12)
        d = random.randint(1, 28)
        return f"{y}-{m:02d}-{d:02d}"
    if any(w in cn for w in ["email"]):
        return f"{random.choice(NAMES).lower()}@example.com"
    if any(w in cn for w in ["phone", "tel"]):
        return f"+1-{random.randint(100,999)}-{random.randint(1000,9999)}"
    if any(w in cn for w in ["url", "website", "link"]):
        return f"https://example.com/{random.choice(WORDS)}"
    if any(w in cn for w in ["desc", "note", "comment", "text", "title", "theme", "type", "status"]):
        return " ".join(random.sample(WORDS, random.randint(1, 3)))
    return random.choice(WORDS) + "_" + random.choice(string.ascii_lowercase)


def gen_number_value(col_name_lower):
    cn = col_name_lower
    if any(w in cn for w in ["year"]):
        return random.randint(1990, 2025)
    if any(w in cn for w in ["age"]):
        return random.randint(18, 75)
    if any(w in cn for w in ["price", "cost", "salary", "amount", "revenue", "budget"]):
        return round(random.uniform(10, 10000), 2)
    if any(w in cn for w in ["count", "number", "num", "quantity"]):
        return random.randint(1, 100)
    if any(w in cn for w in ["percent", "rate", "ratio"]):
        return round(random.uniform(0, 100), 1)
    if any(w in cn for w in ["capacity", "size", "area", "population"]):
        return random.randint(100, 100000)
    if any(w in cn for w in ["height", "weight", "length", "width"]):
        return round(random.uniform(1, 200), 1)
    if any(w in cn for w in ["score", "rating", "rank", "grade"]):
        return round(random.uniform(0, 100), 1)
    if "id" in cn:
        return None  # Will be handled by PK/FK logic
    return random.randint(1, 1000)


def build_db(db_info):
    db_id = db_info["db_id"]
    db_dir = os.path.join(OUTPUT_DIR, db_id)
    os.makedirs(db_dir, exist_ok=True)
    db_path = os.path.join(db_dir, f"{db_id}.sqlite")

    table_names = db_info["table_names_original"]
    columns = db_info["column_names_original"]  # [table_idx, col_name]
    col_types = db_info["column_types"]
    pks = set(db_info["primary_keys"])
    fks = db_info["foreign_keys"]  # [child_col_idx, parent_col_idx]

    # Build FK map: child_col_idx -> parent_col_idx
    fk_map = {child: parent for child, parent in fks}

    # Group columns by table
    table_cols = {}
    for i, (tbl_idx, col_name) in enumerate(columns):
        if tbl_idx < 0:
            continue
        table_cols.setdefault(tbl_idx, []).append((i, col_name, col_types[i]))

    # Topological sort by FK dependencies
    deps = {}
    for tbl_idx in range(len(table_names)):
        deps[tbl_idx] = set()
    for child_idx, parent_idx in fks:
        child_tbl = columns[child_idx][0]
        parent_tbl = columns[parent_idx][0]
        if child_tbl != parent_tbl:
            deps[child_tbl].add(parent_tbl)

    sorted_tables = []
    visited = set()
    def topo(idx):
        if idx in visited:
            return
        visited.add(idx)
        for dep in deps.get(idx, []):
            topo(dep)
        sorted_tables.append(idx)
    for idx in range(len(table_names)):
        topo(idx)

    # Generated PK values per column index
    pk_values = {}

    conn = sqlite3.connect(db_path)
    conn.execute("PRAGMA foreign_keys = ON")

    for tbl_idx in sorted_tables:
        tbl_name = table_names[tbl_idx]
        cols = table_cols.get(tbl_idx, [])
        if not cols:
            continue

        # Create table
        col_defs = []
        pk_col_names = []
        for col_idx, col_name, col_type in cols:
            sql_type = "TEXT" if col_type == "text" else ("REAL" if col_type == "real" else "INTEGER")
            col_defs.append(f'"{col_name}" {sql_type}')
            if col_idx in pks:
                pk_col_names.append(col_name)

        create_sql = f'CREATE TABLE IF NOT EXISTS "{tbl_name}" (\n'
        create_sql += ",\n".join(f"  {d}" for d in col_defs)
        if pk_col_names:
            create_sql += f',\n  PRIMARY KEY ({", ".join(pk_col_names)})'
        create_sql += "\n)"

        try:
            conn.execute(f'DROP TABLE IF EXISTS "{tbl_name}"')
            conn.execute(create_sql)
        except Exception as e:
            print(f"  [WARN] Create {tbl_name}: {e}")
            continue

        # Generate data
        n_rows = ROWS_PER_TABLE
        # For junction tables (all columns are FKs), use fewer rows
        fk_cols_in_table = [ci for ci, _, _ in cols if ci in fk_map]
        if len(fk_cols_in_table) == len(cols):
            n_rows = min(n_rows, 20)

        for row_num in range(n_rows):
            values = []
            skip_row = False
            for col_idx, col_name, col_type in cols:
                cn = col_name.lower()
                if col_idx in fk_map:
                    parent_idx = fk_map[col_idx]
                    parent_vals = pk_values.get(parent_idx, [])
                    if parent_vals:
                        values.append(random.choice(parent_vals))
                    else:
                        values.append(row_num + 1)
                elif col_idx in pks:
                    val = row_num + 1
                    pk_values.setdefault(col_idx, []).append(val)
                    values.append(val)
                elif col_type == "text":
                    values.append(gen_text_value(cn))
                elif col_type in ("number", "integer", "int"):
                    values.append(gen_number_value(cn) or random.randint(1, 100))
                elif col_type == "real":
                    values.append(round(random.uniform(0, 1000), 2))
                else:
                    values.append(gen_text_value(cn))

            placeholders = ",".join(["?"] * len(values))
            col_names_str = ",".join(f'"{c}"' for _, c, _ in cols)
            try:
                conn.execute(f'INSERT INTO "{tbl_name}" ({col_names_str}) VALUES ({placeholders})', values)
            except Exception:
                pass  # Skip rows with constraint violations

    conn.commit()
    conn.close()


def main():
    with open(TABLES_JSON) as f:
        all_dbs = json.load(f)

    os.makedirs(OUTPUT_DIR, exist_ok=True)
    print(f"Generating {len(all_dbs)} databases...")

    for i, db_info in enumerate(all_dbs):
        build_db(db_info)
        if (i + 1) % 20 == 0:
            print(f"  {i+1}/{len(all_dbs)} done")

    print(f"Done. Databases saved to {OUTPUT_DIR}")

    # Verify a few
    for db_id in ["concert_singer", "pets_1", "car_1"]:
        db_path = os.path.join(OUTPUT_DIR, db_id, f"{db_id}.sqlite")
        if os.path.exists(db_path):
            conn = sqlite3.connect(db_path)
            tables = conn.execute("SELECT name FROM sqlite_master WHERE type='table'").fetchall()
            print(f"\n{db_id}: {len(tables)} tables")
            for (tbl,) in tables:
                count = conn.execute(f'SELECT COUNT(*) FROM "{tbl}"').fetchone()[0]
                print(f"  {tbl}: {count} rows")
            conn.close()


if __name__ == "__main__":
    main()
PYEOF
